// ── N: a clamp or reduction inside a numerics contract must be the
// comparison-select form — the fmaxf family launders a NaN into a
// finite value; the select keeps it visible to the consumer that
// validates the data. ──
fn slice_b323_nan_select() -> Vec<KernelRule> {
    vec![KernelRule {
        rule_id: "nan-preserving-select-over-fmaxf-in-scale-reductions".to_string(),
        gpu_concept: "MECHANISM (NaN visibility through a numerics contract; category N — dtype/numerics): a clamp or reduction whose contract is corruption-visible must be the COMPARISON-SELECT form, never the fmaxf family — `v < 0.f ? 0.f : v` keeps a NaN a NaN (the comparison is false, the NaN flows through), `fmaxf(v, 0)` launders it to 0 and the corruption disappears. The amax block reduction uses the NaN-keeping max, verbatim [in-diff] ck_experts.cu:18: 'The larger, or a NaN when either is (fmaxf drops it): a block holding a NaN gets a NaN scale' — `max_nan(a,b) = (a > b || a != a) ? a : b` — so an NVFP4 block holding one NaN gets a NaN SCALE. THE PROPAGATION, stated precisely (the T0 nuance): there is NO downstream refusal gate — the NaN scale propagates (block_scale divides by it, NaN != 0.0, the mul yields NaN) and POISONS the quantized output, which is where the corruption surfaces; author 'propagates/poisons', never 'refuses'. Source: ashhart/TensorFold @ cef366c9 + 2b587959 (Apache-2.0) — ck_experts.cu, experts.cuh (relu2: `b < 0.f ? 0.f : b`), nemotron_ops.cu (the relu arm twice, verbatim: `const float z = s < 0.f ? 0.f : s;  // not fmaxf, which would make a NaN 0`). HONESTY (carry it): the anti-shape is NOT zero in tree — train.cu:549 keeps `const float z = fmaxf(s, 0.f);` on the TRAINING path (outside the inference numerics contract) and contract_controls.cu:355 plants `tf_ctl_pocket_in_fmax` as the contract's DELIBERATE negative control; the law binds the inference contract, not the whole repo. Distinct from the same repo's glm-top1 SELECTION axis (entries_gpu_143 — `first_max_nan` excludes NaN from ever WINNING a pick; THIS propagates a NaN THROUGH a reduction/scale to the output that validates the data — opposite directions, one file) and from finiteness-before-diff-nan-blind-comparison-hole (gpu_99 — the TEST-side blind comparison; THIS is the kernel-side contract). REGIME: clamps/amax reductions feeding quant scales, gate values, or any contract a consumer validates. ANTI-REGIME: paths where a NaN is ALREADY handled upstream; non-contract fast paths that can prove NaN-free inputs. NotBenchable here (a visibility/propagation axis — the fixture pins the select/fmaxf divergence on NaN input, the block-scale poisoning, and clean-path parity). Source: ashhart/TensorFold @ cef366c9+2b587959 — ck_experts.cu, experts.cuh, nemotron_ops.cu, Apache-2.0. Batch 323 / Plan 323.".to_string(),
        ref_shape: "// naive: the fmaxf family in a numerics contract — the NaN\n// is LAUNDERED to a finite value and the corruption disappears\nfn relu_fmaxf(v: f32) -> f32 {\n    v.max(0.0) // IEEE max returns the non-NaN operand: NaN -> 0.0\n}\n\nfn block_amax(block: &[f32]) -> f32 {\n    let mut m = f32::NEG_INFINITY;\n    for &v in block {\n        m = m.max(v.abs()); // one NaN in the block -> a CLEAN scale\n    }\n    m\n}\n\nfn quantized_dot(block: &[f32], scale: f32) -> f32 {\n    block.iter().map(|&v| v * scale).sum() // finite over corrupt data\n}".to_string(),
        opt_pattern: "// optimized: the comparison-select keeps the NaN visible; the\n// amax keeps it through the reduction so the SCALE poisons the\n// output that validates the data (propagation, not a refusal gate)\nfn relu_select(v: f32) -> f32 {\n    // v < 0 ? 0 : v, not fmaxf, which would make a NaN 0.\n    if v < 0.0 { 0.0 } else { v }\n}\n\nfn max_nan(a: f32, b: f32) -> f32 {\n    // The larger, or a NaN when either is (fmaxf drops it).\n    if a > b || a != a { a } else { b }\n}\n\nfn block_amax(block: &[f32]) -> f32 {\n    let mut m = f32::NEG_INFINITY;\n    for &v in block {\n        m = max_nan(m, v.abs()); // a NaN anywhere -> a NaN scale\n    }\n    m\n}\n\nfn quantized_dot(block: &[f32], scale: f32) -> f32 {\n    block.iter().map(|&v| v * scale).sum() // NaN scale -> NaN out\n}\n\n#[test]\nfn nan_visible_through_select_and_scale() {\n    let nan = f32::NAN;\n    assert!(relu_select(nan).is_nan());\n    assert_eq!(relu_fmaxf(nan), 0.0); // the laundering anti-shape\n    assert!(block_amax(&[1.0, nan, 0.5]).is_nan());\n    // clean-path parity: the forms agree when no NaN is present\n    assert_eq!(block_amax(&[1.0, -2.0, 0.5]), 2.0);\n}".to_string(),
    }]
}

// ── D: the launch order is a pure permutation the kernel may remap —
// banding consecutive row-blocks onto one column tile shares the
// weight panel in cache while every output byte stays identical. ──
fn slice_b323_banded_launch() -> Vec<KernelRule> {
    vec![KernelRule {
        rule_id: "banded-launch-order-shares-weight-tiles".to_string(),
        gpu_concept: "MECHANISM (launch-order banding for weight-tile sharing; category D — dispatch, the memory-locality schedule axis): a GEMM's launch order is a PURE PERMUTATION the kernel can remap — `band_tile()` decodes the linear block id so kGemmBand = 4 CONSECUTIVE row-blocks in schedule order walk the column blocks together (band = `first = b / (kGemmBand * cols) * kGemmBand; in_band = b % (kGemmBand * cols); height = min(kGemmBand, rows - first); by = first + in_band % height; bx = in_band / height;`), making the concurrently-resident blocks share each column tile's weights in L2 while the output stays BYTE-IDENTICAL — the only thing that moved is the schedule (the tile swap is `blockIdx.y * kGemmM` -> `by * kGemmM`). The byte-identity is pinned by a digest-equality rig test, verbatim [in-tree] order.zig: '//! The matrix tile's banded block order keeps each tile's bits: its bytes equal the dot2 GEMM tile's on served shapes.' — 14 shapes including the band edges (`edge band` 1300 rows; `edge both` 300×1001×2112). MEASURED (source, gfx1151): a 2048-token pass 8.56 -> 7.48 s, 8192 tokens 35.24 -> 31.04 s; the family guard TF_DEVICE_WMMA_GFX11 gates the wmma tile. Distinct from expert-major-tile-order-token-tile-cache-resident (gpu_39 — the MoE ROUTED-EXPERT enumeration axis, one expert's tiles made adjacent; THIS is the generic dense-GEMM row-band axis where a band of ROW blocks shares a COLUMN tile's weights) and from jit-band-repack-stage-per-use-l1-hot (a repack staging band, not a launch order). REGIME: dense GEMMs whose weight column tiles exceed what one row-block's wave can keep warm — the band converts a cold column walk into a warm one. ANTI-REGIME: grids where the whole weight panel is already L2-resident (the permutation buys nothing); kernels whose output bytes depend on schedule (never legal). NotBenchable here (host-decodable permutation — the fixture pins the bijection, the band-run structure, adjacent-id column sharing, and the edge-band height clamp). Source: ashhart/TensorFold @ 19c491ce — zig/kernels/hip/tiles/gemm.hpp, matrix_gemm.hpp, zig/src/hip/kernel_tests/affine/order.zig, Apache-2.0. Batch 323 / Plan 323.".to_string(),
        ref_shape: "// naive: row-major launch order — concurrent blocks walk DIFFERENT\n// column tiles, so each re-fetches the weight panel cold\nfn linear_tile(b: usize, cols: usize) -> (usize, usize) {\n    (b / cols, b % cols)\n}".to_string(),
        opt_pattern: "// optimized: a banded decode — kGemmBand consecutive row-blocks\n// in schedule order share one column tile's weights in L2; output\n// bytes unchanged (the schedule is the only thing that moved)\nconst K_GEMM_BAND: usize = 4;\n\nfn band_tile(b: usize, rows: usize, cols: usize) -> (usize, usize) {\n    let first = b / (K_GEMM_BAND * cols) * K_GEMM_BAND;\n    let in_band = b % (K_GEMM_BAND * cols);\n    let height = K_GEMM_BAND.min(rows - first);\n    (first + in_band % height, in_band / height) // (by, bx)\n}\n\n#[test]\nfn banded_decode_is_a_permutation_with_band_runs() {\n    let (rows, cols) = (7usize, 16usize); // an edge shape: 7 not a multiple of 4\n    let n = rows * cols;\n    let mut seen = vec![false; n];\n    for b in 0..n {\n        seen[{\n            let (by, bx) = band_tile(b, rows, cols);\n            by * cols + bx\n        }] = true;\n    }\n    assert!(seen.iter().all(|&s| s), \"decode must be a permutation\");\n    // band-run structure: height consecutive ids per column tile, and\n    // adjacent ids inside a run share the column tile\n    let bands = (rows + K_GEMM_BAND - 1) / K_GEMM_BAND;\n    for band in 0..bands {\n        let first = band * K_GEMM_BAND;\n        let height = K_GEMM_BAND.min(rows - first);\n        let base = band * K_GEMM_BAND * cols;\n        for bx in 0..cols {\n            for r in 0..height {\n                assert_eq!(band_tile(base + bx * height + r, rows, cols), (first + r, bx));\n            }\n        }\n    }\n}".to_string(),
    }]
}

// ── L: the tile's index lattice is keyed to the quant format's
// (block, pair, lane) nesting — block reductions and packed writes
// become axis moves over the same lattice, never reshuffles. ──
fn slice_b323_quant_index_space() -> Vec<KernelRule> {
    vec![KernelRule {
        rule_id: "quant-block-keyed-index-space".to_string(),
        gpu_concept: "MECHANISM (the tile index space keyed to the quant block structure; category L — conv-as-GEMM + layout): when a kernel produces a block-quantized output, the TILE's index lattice is laid out to MIRROR the quant format's nesting — verbatim [in-diff] fused_norm_quant.py: 'Index the row as [G, 8, 2]: G groups of 16 (one NVFP4 block each) of 8 (lo, hi) pairs, so block reductions and fp4 packing need no reshapes' — the (g, p, s) view maps to the flat row as g*16 + p*2 + s (a bijection, no data movement), the block amax reduction is an AXIS FOLD over the group's 16 contiguous lanes, and the `cvt.rn.satfinite.e2m1x2` packed pair write reads ADJACENT flat lanes (tl.split into (lo, hi)) — the amax and the pack become axis moves over the SAME lattice, with zero reshuffle of the row. Source: vllm-project/vllm @ 6c19299fc #64509 '[Perf][Qwen3.5] (NVIDIA-only) Fused norm+quant and gate+quant' (Apache-2.0, fused_norm_quant.py +216, `G = next_power_of_2(H) // 16`, the swizzled 128×4 scale store riding the same lattice). The ANTI-SHAPE: a flat-row kernel whose index arithmetic treats the row as scalar lanes — the block reduction then needs a gather/reshape before folding and the packed write a permutation after. Distinct from gqa-reshape-q-down-never-expand-packed-kv (gpu_99 — reshape-DOWN avoidance over an EXISTING layout; THIS designs the lattice so no reshape exists to avoid), from planar-transposed-activation-multi-column-quant-matvec (gpu_49 — activation planes keyed to per-thread COALESCING; THIS is keyed to the quant format's block/pair/lane nesting), and from host-scratch-mirrors-slot-order-for-coalesced-writes (a host-side mirror of slot order, not the tile lattice). REGIME: block-quantized producers (NVFP4/MXFP4-class formats with (block, pair) nesting). ANTI-REGIME: scalar quant formats with no block structure; consumers needing a different nesting (the lattice IS the contract with the pack). NotBenchable here (an index-arithmetic axis — the fixture pins the bijection, the axis-fold equivalence, and the pack adjacency). Source: vllm-project/vllm @ 6c19299fc #64509 — vllm/models/qwen3_5/nvidia/ops/fused_norm_quant.py, Apache-2.0. Batch 323 / Plan 323.".to_string(),
        ref_shape: "// naive: the flat-row view — the block reduction needs a gather\n// out of the row and the packed write a permutation back\nfn block_amax_flat(row: &[f32], g: usize) -> f32 {\n    // the block's lanes are NOT addressable as an axis: gather each\n    let mut m = 0.0f32;\n    for p in 0..8 {\n        for s in 0..2 {\n            let i = g * 16 + p * 2 + s; // recomputed per element\n            m = m.max(row[i].abs());\n        }\n    }\n    m\n}".to_string(),
        opt_pattern: "// optimized: the [G, 8, 2] lattice mirrors the quant format —\n// the amax is an axis fold over the group's contiguous lanes and\n// the packed (lo, hi) write reads adjacent lanes; no reshapes\nconst BLOCK: usize = 16;\n\nfn idx(g: usize, p: usize, s: usize) -> usize {\n    g * BLOCK + p * 2 + s // (group, pair, side) -> flat\n}\n\nfn block_amax(row: &[f32], g: usize) -> f32 {\n    (0..BLOCK).map(|i| row[g * BLOCK + i].abs()).fold(0.0f32, f32::max)\n}\n\n#[test]\nfn lattice_is_bijection_and_axis_folds() {\n    let h = 32usize;\n    let g_count = h / BLOCK;\n    let row: Vec<f32> = (0..h).map(|i| i as f32).collect();\n    // the lattice covers the flat row bijectively\n    let mut seen = vec![false; h];\n    for g in 0..g_count {\n        for p in 0..8 {\n            for s in 0..2 {\n                seen[idx(g, p, s)] = true;\n            }\n        }\n    }\n    assert!(seen.iter().all(|&s| s));\n    // the block reduction IS an axis fold over contiguous lanes\n    let manual = row[16..32].iter().fold(0.0f32, |m, &v| m.max(v.abs()));\n    assert_eq!(block_amax(&row, 1), manual);\n    // the pack pair sits adjacent — no permutation\n    assert_eq!(idx(1, 3, 1), idx(1, 3, 0) + 1);\n}".to_string(),
    }]
}

// ── A: an MMA fragment stored element-by-element is a codegen cliff on
// the silicon it crawls on — store each lane's pair whole, bit-identical,
// with the admission selected PER GPU GENERATION by measurement. ──
fn slice_b323_whole_store() -> Vec<KernelRule> {
    vec![KernelRule {
        rule_id: "simdgroup-fragment-whole-store-generation-keyed".to_string(),
        gpu_concept: "MECHANISM (fragment store shape, admission per generation; category A — memory access): a `simdgroup_matrix<bfloat, 8, 8>` fragment stored/loaded ELEMENT-BY-ELEMENT through `thread_elements()[0]`/`[1]` is a CODEGEN CLIFF on M1-class silicon — verbatim [in-commit] 0afc366c: 'On an M1 Pro that ran every prompt tile at 0.04 TFLOPS: a 2,048-row LFM2 chunk took 243 s'; the fix stores each lane's pair WHOLE through a vector reinterpret over the same registers, verbatim [in-diff] tile_qmm.metal: `reinterpret_cast<thread vec<bfloat, 2>&>(a[i].thread_elements()) = *(const threadgroup vec<bfloat, 2>*)ap;` (a float2 twin for the accumulator) — arithmetic bit-identical ('q4, q6 and q8 tiles give bit-identical outputs at 2048x2048x512, 6144x2048x2048 and 2048x6144x37'), tiles 0.04 -> 2.38–2.71 TFLOPS (62–78×). THE ADMISSION IS PER-GENERATION, verbatim [in-tree] tile_qmm.zig: 'M1 and M2 (13, 14) store MMA fragments whole, later GPUs by element' — the kernel SOURCE is selected by `device.generation()` (`if (generation == 13 or generation == 14) whole_fragments else sources.core_tile_qmm`; whole_fragments prepends `#define TF_TQ_WHOLE_FRAGMENTS 1`), with the test named verbatim 'M1 and M2 take whole-fragment tiles, later GPUs and unknown ones the shipped source' (13/14 -> whole; {0, 15, 16, 17} -> shipped). THE GATE IS LOAD-BEARING, not cosmetic: the follow-up bfb0f5a2 exists because M3 Ultra decode REGRESSED 1.8–2.3% with whole stores — the #else element branch is deliberate. HONESTY (carry it): the M2 is admitted on the M1's evidence and was never measured (CHANGELOG: 'the M2 takes the M1's path on its evidence and was not measured'). Distinct from fewrow-mma-fragment-matvec-silicon-tiered-dispatch (gpu_119 — the fragment CARRIER for few-row matvec, its silicon tiers are batch-size RUNGS; THIS is the store SHAPE with a GPU-GENERATION admission), from mma-fragment-layout-m16n8k16 + simdgroup-row-packing-reduction-amortization (fragment layouts/packing for reduction amortization — neither owns the element-vs-whole store cliff), and from the gpu_98 prescale rule whose thread_elements hits are the masked-in-place QUOTES (a different atom). REGIME: Metal fragment stores/loads on a per-generation-selected source. ANTI-REGIME: generations measured to LOSE from whole stores (the element branch stays); sources shared across generations without a gate. NotBenchable here (a Metal codegen cliff — the fixture pins store-shape bit-identity and the generation gate). Source: ashhart/TensorFold @ 0afc366c+bfb0f5a2 #1590 — zig/kernels/metal/core/tile_qmm.metal, zig/src/core/tile_qmm.zig, Apache-2.0. Batch 323 / Plan 323.".to_string(),
        ref_shape: "// naive: the fragment walked out two scalar stores per lane — the
// shape the compiler lowers badly on M1-class silicon
fn store_by_elements(pair: [f32; 2], out: &mut [f32], base: usize) {
    out[base] = pair[0];
    out[base + 1] = pair[1];
}".to_string(),
        opt_pattern: "// optimized: the pair stored WHOLE through a vector reinterpret —
// bit-identical, one wide store; the admission is per-generation
fn store_whole(pair: [f32; 2], out: &mut [f32], base: usize) {
    let as_vec: [f32; 2] = pair; // the reinterpret — same bits
    out[base..base + 2].copy_from_slice(&as_vec);
}

fn selects_whole_store_source(generation: u32) -> bool {
    // M1 and M2 (13, 14) store MMA fragments whole; later GPUs and
    // unknown ones take the shipped element-store source
    generation == 13 || generation == 14
}

#[test]
fn whole_store_bit_identical_and_generation_keyed() {
    let f = [1.5f32, -2.25];
    let mut a = [0.0f32; 2];
    let mut b = [0.0f32; 2];
    a.copy_from_slice(&f); // the element-store result
    store_whole(f, &mut b, 0);
    assert_eq!(a[0].to_bits(), b[0].to_bits());
    assert_eq!(a[1].to_bits(), b[1].to_bits());
    assert!(selects_whole_store_source(14));
    assert!(!selects_whole_store_source(15)); // later GPU: shipped source
    assert!(!selects_whole_store_source(0)); // unknown: shipped source
}".to_string(),
    }]
}

// ── A: which buffer class gets L1 allocation is keyed on REUSE
// (stream-through vs revisited), never on read-only-ness alone — the
// once-read weight stream must not allocate L1 lines. ──
fn slice_b323_l1_policy() -> Vec<KernelRule> {
    vec![KernelRule {
        rule_id: "stream-through-load-no-l1-allocate-once-read".to_string(),
        gpu_concept: "MECHANISM (L1 allocation policy keyed on reuse; category A — memory access, the cache-policy family): a weight stream read ONCE per token and never revisited loads through `ld.global.nc.L1::no_allocate` — cache-policy-only, the value bit-identical ('bit-identical by construction and proven by reply digest, with the read-only path kept'), the read-only marking kept — because `__ldg` ALLOCATES its lines in L1 and, verbatim [in-commit] acb21860: 'on a 163 GiB stream that fills L1 with lines nothing will ask for again, evicting the activations and the small tables that are reused every round'. THE ATOM: which buffer class gets L1 allocation is keyed on REUSE (stream-through vs revisited), NEVER on read-only-ness alone — `nc` answers the read-only (coherence) half, `L1::no_allocate` the reuse half. The codebase split IS the law: the decode paths' once-read trellis stream takes `asm volatile(\"ld.global.nc.L1::no_allocate.u32 %0, [%1];\" : \"=r\"(v) : \"l\"(p))` (ldg_stream_u32, consumed by ldg_lane_words), while the prefill load_step paths KEEP `__ldg` CORRECTLY — in a prompt pass multiple row-blocks re-read the same weight tiles (revisited within the call). The in-code comment pins the value contract, verbatim [in-diff] exl3_decode.cuh: '// The weight stream is read once, so do not allocate L1 for it: same value as __ldg, cache policy only.' HONESTY (carry it): 'Not the whole difference, and measured before claiming' — the remaining gap (production's lanes read 16 contiguous bytes vs our 8; 1–4-step warp-slice staging) is disclosed as separate re-tile work; MEASURED (CHANGELOG #1534): decode +2.3% one stream, +0.5–2.3% at 2–8 streams on three GB10s at TP=3. Distinct from weight-stream-non-temporal-loads (gpu_07 — the L2 evict-first policy, `__ldcs`/nontemporal: a DIFFERENT CACHE LEVEL on the same stream class; a kernel can need BOTH — compose, never merge: that rule's regime split is streaming-vs-reused operands at L2, THIS is L1 allocation for the once-read stream) and from coherence-scope-by-write-set-ordinary-loads-on-immutable (write-set coherence scoping vs a LOAD cache policy). REGIME: once-read streams beside a small revisited working set. ANTI-REGIME: revisited buffers (the hint evicts the reuse the cache exists for — gpu_07's inverse regime at L1); architectures where the policy is a no-op. NotBenchable here (a cache-policy axis — the fixture pins the reuse-keyed policy split and value bit-identity). Source: ashhart/TensorFold @ acb21860+839778d4+5e151065 #1534 — zig/kernels/cuda/exl3_decode.cuh (+ the exl3_experts/exl3_linear decode paths), Apache-2.0. Batch 323 / Plan 323.".to_string(),
        ref_shape: "// naive: every read-only load goes through __ldg — including the\n// once-read weight stream, whose lines ALLOCATE in L1 and evict the\n// activations/tables that are reused every round\n#[derive(Clone, Copy)]\nenum LoadPolicy { LdgReadOnly }\n\nfn policy_for(_revisited: bool) -> LoadPolicy {\n    LoadPolicy::LdgReadOnly // read-only-ness alone decides: WRONG axis\n}".to_string(),
        opt_pattern: "// optimized: the policy keyed on REUSE - the once-read stream takes\n// ld.global.nc.L1::no_allocate (read-only kept, no L1 line); tiles\n// revisited within the call keep the allocating read-only load\n#![allow(dead_code)]\n\n#[derive(Clone, Copy, PartialEq, Debug)]\nenum LoadPolicy {\n    StreamNoAllocate, // ld.global.nc.L1::no_allocate\n    LdgReadOnly,      // __ldg - allocates L1\n}\n\nfn policy_for(revisited_within_call: bool) -> LoadPolicy {\n    if revisited_within_call { LoadPolicy::LdgReadOnly } else { LoadPolicy::StreamNoAllocate }\n}\n\nfn stream_load(buf: &[u32], i: usize, _policy: LoadPolicy) -> u32 {\n    buf[i] // cache policy only - the value never moves\n}\n\n#[test]\nfn policy_keyed_on_reuse_not_readonly() {\n    // decode: the weight stream is read once, never revisited\n    assert_eq!(policy_for(false), LoadPolicy::StreamNoAllocate);\n    // prefill: row-blocks re-read the same weight tiles in-call\n    assert_eq!(policy_for(true), LoadPolicy::LdgReadOnly);\n    // the L1 policy is CACHE-ONLY: the value read is bit-identical\n    // under either policy (never a numerics axis)\n    let buf = [7u32, 9];\n    assert_eq!(stream_load(&buf, 0, LoadPolicy::StreamNoAllocate), stream_load(&buf, 0, LoadPolicy::LdgReadOnly));\n    // the read-only-ness axis is the WRONG axis: both policies load\n    // read-only data - reuse, not const-ness, must pick the policy\n    assert_ne!(policy_for(false), policy_for(true));\n}\n".to_string(),
    }]
}

// ── B: a select per accumulator element plus a runtime division in the
// K-loop body is a register-pressure cliff before it is an ALU cost —
// shift+mask and a uniform branch when the divisor is a compile-time
// power of two. ──
fn slice_b323_shift_mask() -> Vec<KernelRule> {
    vec![KernelRule {
        rule_id: "inner-loop-select-division-shift-mask-vgpr-pressure".to_string(),
        gpu_concept: "MECHANISM (inner-loop op form vs register pressure; category B — compute): a select per accumulator element (`first ? zero : d`) plus a RUNTIME division/modulo by the stages-per-group count pushed the tile to 256 VGPRs and SPILLED INSIDE THE K LOOP — the spill, not the ALU work, is the loss. When the divisor is a compile-time power of two the group index/bounds become shift+mask, verbatim [in-diff] matrix_gemm.hpp: `const int per_log2 = __builtin_ctz(per); auto group_of = [&](int st) { return st >> per_log2; }; auto group_end = [&](int st) { return (st & (per - 1)) == per - 1; };` and the first-product init becomes a uniform branch, verbatim [in-diff]: 'A group's first product starts from zero on a uniform branch, not a select per accumulator.' Byte-identity, verbatim [in-commit] 33b443da: 'Every sum is the same in the same order, so the bytes are unchanged; the kernel no longer spills.' MEASURED (source, gfx1151 — cite the commit message; the CHANGELOG's twin says 8.60->5.83 s and names the after-state 248 registers, 256 was the BEFORE-state VGPR count): 'the seven shapes take 63.7 ms instead of 105.8 ms (15.3 to 24.4 TFLOPS on gate_up). A prompt pass of 2048 tokens: 8.49 to 5.78 s'; the old form was `term(a, base + st / per)`, `st % per == per - 1`, `first ? zero : d` with runtime `per = a.group / kGemmK`. THE PRECONDITION IS LOAD-BEARING, verbatim [in-diff]: 'groups are 32, 64 or 128 codes: one, two or four stages' — per ∈ {1, 2, 4} is what makes ctz legal; a general 'replace division with shift' rule WITHOUT that domain pin would be wrong (a runtime non-power-of-two divisor must keep the division). Anti-shape check: grep 'first ? zero' over zig/kernels/hip/ -> ZERO hits at the pin (the cliff is gone). Distinct from constexpr-unroll-capacity-bound-zero-guard-holds-array-in-registers (O — array RESIDENCY via compile-time capacity bounds; THIS is inner-loop OP-FORM elimination: select/division -> shift/mask/uniform-branch to keep the register budget under the spill line) and from register-budget-band-partition-indep-correction-offband (a band-correction budget). REGIME: K-loop bodies selecting on a stage boundary or dividing by a stage count known at compile time. ANTI-REGIME: runtime divisors that are not compile-time powers of two (keep the division); spills NOT caused by per-element selects (a different pressure source). NotBenchable here (an op-form axis — the fixture pins the shift/mask equivalence on the legal divisors and the byte-identical accumulation chains). Source: ashhart/TensorFold @ 33b443da #1663 — zig/kernels/hip/tiles/matrix_gemm.hpp, Apache-2.0. Batch 323 / Plan 323.".to_string(),
        ref_shape: "// naive: a select per accumulator element + a runtime division in\n// the K-loop body — the VGPR budget breaks and the loop spills\nfn stage_of_runtime(st: usize, per: usize) -> usize {\n    st / per // runtime divisor\n}\n\nfn stage_end_runtime(st: usize, per: usize) -> bool {\n    st % per == per - 1\n}\n\nfn first_select(first: bool, zero: f32, d: f32) -> f32 {\n    if first { zero } else { d } // materialized PER ELEMENT\n}".to_string(),
        opt_pattern: "// optimized: shift+mask for the compile-time power-of-two divisor,\n// a uniform branch for the first-product init — same sums in the same\n// order, the kernel no longer spills\nfn stage_of_shift(st: usize, per_log2: u32) -> usize {\n    st >> per_log2 // per_log2 = ctz(per), compile-time\n}\n\nfn stage_end_mask(st: usize, per: usize) -> bool {\n    st & (per - 1) == per - 1\n}\n\nfn first_uniform_branch(first: bool, zero: f32, d: f32) -> f32 {\n    if first { zero } else { d } // one branch per GROUP, the tile uniform\n}\n\n/// The accumulation chain both forms must reproduce.\nfn accumulate(use_shift_form: bool, stages: usize, per: usize) -> f32 {\n    let per_log2 = per.trailing_zeros();\n    let mut acc = 0.0f32;\n    let mut first = true;\n    for st in 0..stages {\n        let boundary = if use_shift_form { stage_end_mask(st, per) } else { stage_end_runtime(st, per) };\n        let _stage = if use_shift_form { stage_of_shift(st, per_log2) } else { stage_of_runtime(st, per) };\n        let contrib = ((st % 7) as f32) * 0.25 + 1.0;\n        acc = if use_shift_form {\n            if first { first_uniform_branch(first, 0.0, contrib) } else { acc + contrib }\n        } else if first {\n            first_select(first, 0.0, contrib)\n        } else {\n            acc + contrib\n        };\n        first = boundary; // the step AFTER a boundary starts the new group\n    }\n    acc\n}\n\n#[test]\nfn shift_mask_equivalent_and_chain_bit_identical() {\n    // the precondition is load-bearing: per in {1, 2, 4} only\n    for &per in &[1usize, 2, 4] {\n        let log2 = per.trailing_zeros();\n        for st in 0..256 {\n            assert_eq!(stage_of_runtime(st, per), stage_of_shift(st, log2));\n            assert_eq!(stage_end_runtime(st, per), stage_end_mask(st, per));\n        }\n        // every sum the same in the same order -> the bytes are unchanged\n        let a = accumulate(false, 16, per);\n        let b = accumulate(true, 16, per);\n        assert_eq!(a.to_bits(), b.to_bits());\n    }\n}".to_string(),
    }]
}

// ── L: the ACTIVATION storage layout is permuted to mirror the
// consumer's weight bit-plane decomposition — bit j of every packed
// weight byte pairs with byte i of activation word j, and the dot
// becomes eight aligned bit-plane products with zero weight unpacking. ──
fn slice_b323_activation_bitplane() -> Vec<KernelRule> {
    vec![KernelRule {
        rule_id: "activation-layout-mirrors-weight-bit-serialism".to_string(),
        gpu_concept: "MECHANISM (activation layout keyed to the weight's bit decomposition; category L — layout): the Q1_0 one-column mat-vec re-lays the ACTIVATION as GGML_CUDA_Q8_1_Q1B — verbatim [in-tree] common.cuh (the new enum arm, GGML_CUDA_Q8_1_Q1B = 4): 'word j = elements j, 8+j, 16+j, 24+j (byte i = element 8*i + j)' (the store comment pins the byte form, quantize.cu: `((int8_t *) ycol)[kb*QK8_1 + 4*(e % 8) + e / 8] = q;`) — so bit j of every packed weight byte lines up with word j of the activations, making the dot EIGHT aligned dp4a on masked bit-planes (vecdotq.cuh vec_dot_q1_0_q1b: `ggml_cuda_dp4a((q >> j) & 0x01010101, ...)` for j 0..8) — exact int32, verbatim [in-tree]: 'all in int32, so the result equals vec_dot_q1_0_q8_1 exactly'. THE NEW ATOM is the ACTIVATION-side (producer) plane layout KEYED to the consumer's bit-serialism: the weight-side mask `(q >> j) & 0x01010101` is INCORRECT without this exact permutation (bit j of weight byte i must meet element 8i + j), and composition cannot derive the producer-side invariant — it is what makes the composition valid. THE SIGN ALGEBRA rides the EXISTING isum half-slot, never new work, verbatim [in-diff] vecdotq.cuh: `const int sumi = 2*s - (int) __half_as_short(__high2half(ds));` (sum((2b−1)a) = 2·sum(ba) − sum(a); the quantize writes (d, isum) into the same ds half2 slot as the plain block_q8_1 path — 'same row stride as block_q8_1', the launcher never notices). ADMISSION (the family shape): FOUR rows per CTA for Q1_0 vs the 2-row default (mmvq.cu calc_rows_per_block: `mmvq_two_rows_ncols1(type) ? (type == GGML_TYPE_Q1_0 ? 4 : 2) : 1`); Turing+ with the demote-only env kill-switch GGML_CUDA_Q1_BITSERIAL ('=0 keeps the plain block_q8_1 layout (A/B switch)'), batch-invariant opt-out, DGX_SPARK excluded, HIP/MUSA-excluded, ncols_dst == 1 only. The fork's own PQ2_0 header carries the same family shape (the code-word/activation-bytes pairing) — THIS is the bit-plane-serial instance of the general law. COMPOSES (never merges): bit-plane-plane-sums-input-side-offset-dot (B11 — the weight-side bit-plane dot form; THIS is the producer-side layout that makes it correct) + deferred-bias-ternary-dp4a-exact-isum (gpu_49 — the isum half-slot transport reused verbatim). Distinct from planar-transposed-activation-multi-column-quant-matvec (gpu_49 — activation planes keyed to per-thread COALESCING/multi-column traffic; THIS is keyed to the WEIGHT's bit decomposition) and from register-built-right-operand-lane-contiguous-plane-layout (gpu_60 — a weight-side lane layout for MMA operands). GREP EVIDENCE: 'permuted activation / word j / 8+j' -> no owner in corpus. REGIME: bit-serial weight consumers whose masks assume an activation byte order the producer does not ship. ANTI-REGIME: consumers that unpack weights anyway (no pairing needed); batch-invariant or non-Turing paths. NotBenchable here (a layout-pairing axis — the fixture pins the (i, j) pairing law, the bit-plane dot exactness, and the 2·sum(ba) − sum(a) algebra). Source: PrismML-Eng/llama.cpp @ 01ea7fcf #420 — ggml/src/ggml-cuda/{common.cuh, mmvq.cu, quantize.cu, vecdotq.cuh} (87+/3−), MIT (the PRIMARY PrismML/llama.cpp spelling 404s; PrismML-Eng is canonical). Batch 323 / Plan 323.".to_string(),
        ref_shape: "// naive: the activation ships in its stock layout and the weight\n// consumer unpacks every byte to find bit j's element\nfn weight_bit_of(w_bytes: &[u8], e: usize) -> u8 {\n    let (byte_i, bit_j) = (e / 8, e % 8);\n    (w_bytes[byte_i] >> bit_j) & 1 // the consumer unpacks per element\n}".to_string(),
        opt_pattern: "// optimized: the activation layout PERMUTED to mirror the weight's\n// bit-serialism — bit j of weight byte i pairs with byte i of\n// activation word j; the dot is eight aligned bit-plane products\n\n/// Activation layout: element e lives at (word e % 8, byte e / 8).\nfn activation_pos(e: usize) -> (usize, usize) {\n    (e % 8, e / 8) // (word j, byte i)\n}\n\n/// Weight layout: byte i holds the bits of elements {8i .. 8i+7}.\nfn weight_pos(e: usize) -> (usize, usize) {\n    (e / 8, e % 8) // (byte i, bit j)\n}\n\n/// sum(b·a) over the bit planes (the dp4a-equivalent, byte-serial).\nfn dot_bit_serial_raw(w_bytes: &[u8], a_words: &[u32]) -> i32 {\n    let mut acc = 0i32;\n    for j in 0..8 {\n        for i in 0..4 {\n            let bit = ((w_bytes[i] >> j) & 1) as i32;\n            let a_byte = ((a_words[j] >> (8 * i)) & 0xFF) as u8;\n            acc += bit * (a_byte as i8 as i32);\n        }\n    }\n    acc\n}\n\n#[test]\nfn layouts_pair_and_dot_exact() {\n    // the pairing law: both layouts meet at (i, j) for every element\n    for e in 0..32 {\n        let (wi, wj) = weight_pos(e);\n        let (aw, ab) = activation_pos(e);\n        assert_eq!((wj, wi), (aw, ab), \"element {e}: layouts do not pair\");\n    }\n    let w_bytes: Vec<u8> = (0..4).map(|i| (i * 37 + 11) as u8).collect();\n    let a_words: Vec<u32> = (0..8)\n        .map(|j| (0..4).map(|i| ((i * 13 + j * 7) % 200) as u32).fold(0u32, |acc, b| (acc << 8) | b))\n        .collect();\n    // exactness vs the naive per-element reference\n    let mut sum_ba_ref = 0i32;\n    for e in 0..32 {\n        let (wi, wj) = weight_pos(e);\n        let bit = ((w_bytes[wi] >> wj) & 1) as i32;\n        let a_byte = ((a_words[wj] >> (8 * wi)) & 0xFF) as i8 as i32;\n        sum_ba_ref += bit * a_byte;\n    }\n    assert_eq!(dot_bit_serial_raw(&w_bytes, &a_words), sum_ba_ref);\n    // the sign algebra rides the isum half: sum((2b−1)a) = 2·sum(ba) − sum(a)\n    let sum_a: i32 = (0..8).map(|j| (0..4).map(|i| ((a_words[j] >> (8 * i)) & 0xFF) as i8 as i32).sum::<i32>()).sum();\n    let mut signed_ref = 0i32;\n    for e in 0..32 {\n        let (wi, wj) = weight_pos(e);\n        let bit = ((w_bytes[wi] >> wj) & 1) as i32;\n        let a_byte = ((a_words[wj] >> (8 * wi)) & 0xFF) as i8 as i32;\n        signed_ref += (2 * bit - 1) * a_byte;\n    }\n    assert_eq!(2 * dot_bit_serial_raw(&w_bytes, &a_words) - sum_a, signed_ref);\n}".to_string(),
    }]
}

